package it.cavallium.rockserver.core.common.distributed;

import java.io.*;
import java.security.*;
import java.util.*;

/** Complete declared database vector. Authority freshness and simultaneous cohort capture belong to the driver. */
public final class DatabaseBackupDefinition {
    public static final int MAX_BYTES=64*1024*1024,MAX_RANGES=DatabaseDomainRoster.MAX_DOMAINS*RangeDirectoryCodec.MAX_RANGES;
    public record Limits(int maximumRanges,int maximumColumnPairs,int maximumChunks,long maximumArchiveBytes,int maximumMetadataBytes) {
        public Limits {if(maximumRanges<1 || maximumRanges>MAX_RANGES || maximumColumnPairs<1 || maximumColumnPairs>MAX_RANGES*RangeDirectoryCodec.MAX_COLUMNS || maximumChunks<1 || maximumChunks>1048576 || maximumArchiveBytes<1 || maximumMetadataBytes<1 || maximumMetadataBytes>MAX_BYTES)throw new IllegalArgumentException("Invalid global backup limits");}
    }
    public record Domain(RangeDirectory directory,DistributedSchema schema,List<SnapshotFence> fences) {
        public Domain {Objects.requireNonNull(directory);Objects.requireNonNull(schema);schema.requireMatches(directory);fences=List.copyOf(fences);if(directory.columns().isEmpty()){if(!fences.isEmpty())throw new IllegalArgumentException("Empty schema cannot invent capture participants");}else if(fences.isEmpty())throw new IllegalArgumentException("Backup requires real full-column subfences");
            var covered=new HashSet<UUID>();for(var fence:fences){if(!fence.clusterId().equals(directory.clusterId()) || !fence.databaseId().equals(directory.databaseId()) || fence.domains().size()!=1 || !DomainBinding.of(directory).equals(fence.domains().getFirst()))throw new IllegalArgumentException("Backup subfence changed domain vector");
                for(var participant:fence.participants()){var range=directory.ranges().stream().filter(r->r.groupId().equals(participant.groupId())).findFirst().orElseThrow(()->new IllegalArgumentException("Foreign backup group"));if(!covered.add(range.groupId()) || !range.rangeId().equals(participant.rangeId()) || range.rangeEpoch()!=participant.rangeEpoch() || !Arrays.equals(participant.schemaDigest(),schema.digest()))throw new IllegalArgumentException("Duplicate/changed backup range");
                    var columns=new HashSet<UUID>();for(var span:participant.scope().spans())if(span.isPoint() || !columns.add(span.columnId()) || !Arrays.equals(span.lowerInclusive(),range.lowerInclusive()) || !Arrays.equals(span.upperExclusive(),range.upperExclusive()))throw new IllegalArgumentException("Backup subfence must cover complete column intervals");if(!columns.equals(directory.columns()))throw new IllegalArgumentException("Incomplete backup column scope");}
            }
            if(!directory.columns().isEmpty() && (covered.size()!=directory.ranges().size() || directory.ranges().stream().anyMatch(r->r.topologyState()!=RangeDescriptor.TopologyState.ACTIVE)))throw new IllegalArgumentException("Backup lacks complete ACTIVE domain coverage");
        }
    }
    private final UUID backupId;private final DatabaseDomainRoster roster;private final List<Domain> domains;private final Limits limits;private final byte[] encoded;
    public DatabaseBackupDefinition(UUID backupId,DatabaseDomainRoster roster,Collection<Domain> domains,Limits limits){this.backupId=Objects.requireNonNull(backupId);this.roster=Objects.requireNonNull(roster);this.limits=Objects.requireNonNull(limits);this.domains=domains.stream().sorted(Comparator.comparing(d->d.directory().domainId(),RangeDirectoryCodec.UUID_ORDER)).toList();var ids=new HashSet<UUID>();var groups=new HashSet<UUID>();var rangeIds=new HashSet<UUID>();var columns=new HashSet<UUID>();var apiIds=new HashSet<Long>();var fences=new HashSet<UUID>();long pairs=0;
        for(var domain:this.domains){var directory=domain.directory();if(!ids.add(directory.domainId()) || !directory.clusterId().equals(roster.clusterId()) || !directory.databaseId().equals(roster.databaseId()))throw new IllegalArgumentException("Backup roster/vector namespace changed");for(var range:directory.ranges())if(!groups.add(range.groupId()) || !rangeIds.add(range.rangeId()))throw new IllegalArgumentException("Backup DATA group/range is shared by domains");for(var column:domain.schema().columns())if(!columns.add(column.columnId()) || !apiIds.add(column.apiId()))throw new IllegalArgumentException("Backup logical column/API ID is shared by domains");for(var fence:domain.fences())if(!fences.add(fence.fenceId()))throw new IllegalArgumentException("Backup subfence identity reused");pairs+=(long)directory.ranges().size()*directory.columns().size();}
        if(!ids.equals(new HashSet<>(roster.domainIds())) || groups.size()>limits.maximumRanges() || pairs>limits.maximumColumnPairs() || pairs>limits.maximumChunks())throw new IllegalArgumentException("Backup roster/coverage exceeds declared global bounds");encoded=BackupData.bytes(out->{out.writeInt(0x44424244);BackupData.uuid(out,backupId);BackupData.blob(out,roster.encode());out.writeInt(limits.maximumRanges());out.writeInt(limits.maximumColumnPairs());out.writeInt(limits.maximumChunks());out.writeLong(limits.maximumArchiveBytes());out.writeInt(limits.maximumMetadataBytes());out.writeInt(this.domains.size());for(var domain:this.domains){BackupData.blob(out,RangeDirectoryCodec.encode(domain.directory()));BackupData.blob(out,DistributedSchemaCodec.encode(domain.schema()));out.writeInt(domain.fences().size());for(var fence:domain.fences())BackupData.blob(out,fence.encode());}},limits.maximumMetadataBytes());
    }
    public UUID backupId(){return backupId;}public DatabaseDomainRoster roster(){return roster;}public List<Domain> domains(){return domains;}public Limits limits(){return limits;}public byte[] encode(){return encoded.clone();}public byte[] digest(){return BackupData.hash(encoded);}
    public Domain domain(UUID id){return domains.stream().filter(d->d.directory().domainId().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown backup domain"));}
    public void requireVector(DatabaseDomainRoster current,Collection<Domain> vector){if(!Arrays.equals(roster.encode(),current.encode()) || !Arrays.equals(encoded,new DatabaseBackupDefinition(backupId,current,vector,limits).encode()))throw new IllegalArgumentException("Backup authoritative roster/vector changed");}
    public static DatabaseBackupDefinition decode(byte[] bytes){return BackupData.read(bytes,MAX_BYTES,in->{if(in.readInt()!=0x44424244)throw new IOException("Wrong backup definition");UUID id=BackupData.uuid(in);var roster=DatabaseDomainRoster.decode(BackupData.blob(in,DatabaseDomainRoster.MAX_BYTES));var limits=new Limits(in.readInt(),in.readInt(),in.readInt(),in.readLong(),in.readInt());int n=BackupData.count(in,DatabaseDomainRoster.MAX_DOMAINS,12);var domains=new ArrayList<Domain>();for(int d=0;d<n;d++){var directory=RangeDirectoryCodec.decode(BackupData.blob(in,RangeDirectoryCodec.MAX_ENCODED_BYTES));var schema=DistributedSchemaCodec.decode(BackupData.blob(in,DistributedSchemaCodec.MAX_BYTES));int f=BackupData.count(in,MAX_RANGES);var fences=new ArrayList<SnapshotFence>();for(int j=0;j<f;j++)fences.add(SnapshotFence.decode(BackupData.blob(in,SnapshotFence.MAX_BYTES)));domains.add(new Domain(directory,schema,fences));}var result=new DatabaseBackupDefinition(id,roster,domains,limits);BackupData.canonical(bytes,result.encode());return result;});}
}
final class BackupData {
    @FunctionalInterface interface Write{void write(DataOutputStream out)throws IOException;}@FunctionalInterface interface Read<T>{T read(DataInputStream in)throws IOException;}
    static byte[] bytes(Write write,int maximum){try{var buffer=new ByteArrayOutputStream();var bounded=new OutputStream(){int size;void reserve(int count){if(count<0 || count>maximum-size)throw new IllegalArgumentException("Backup metadata exceeds bound before growth");size+=count;}@Override public void write(int value){reserve(1);buffer.write(value);}@Override public void write(byte[] bytes,int offset,int count){reserve(count);buffer.write(bytes,offset,count);}};write.write(new DataOutputStream(bounded));return buffer.toByteArray();}catch(IOException impossible){throw new UncheckedIOException(impossible);}}
    static <T>T read(byte[] bytes,int maximum,Read<T> read){if(bytes==null || bytes.length>maximum)throw new IllegalArgumentException("Backup metadata length exceeds bound");try{var in=new DataInputStream(new ByteArrayInputStream(bytes));var result=read.read(in);if(in.available()!=0)throw new IOException("Trailing backup metadata");return result;}catch(IOException invalid){throw new IllegalArgumentException("Invalid backup metadata",invalid);}}
    static void uuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    static void blob(DataOutputStream out,byte[] bytes)throws IOException{out.writeInt(bytes.length);out.write(bytes);}static byte[] blob(DataInputStream in,int max)throws IOException{int n=in.readInt();if(n<0 || n>max || n>in.available())throw new IOException("Backup blob exceeds bound");return in.readNBytes(n);}
    static int count(DataInputStream in,int max)throws IOException{return count(in,max,4);}static int count(DataInputStream in,int max,int minimumBytes)throws IOException{int n=in.readInt();if(n<0 || n>max || (long)n*minimumBytes>in.available())throw new IOException("Backup count exceeds bound/remaining bytes");return n;}static void canonical(byte[] original,byte[] actual){if(!Arrays.equals(original,actual))throw new IllegalArgumentException("Noncanonical backup metadata");}
    static byte[] hash(byte[] bytes){try{return MessageDigest.getInstance("SHA-256").digest(bytes);}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
    static byte[] nullable(byte[] bytes){return bytes==null?null:bytes.clone();}static void bound(DataOutputStream out,byte[] bytes)throws IOException{if(bytes==null)out.writeInt(-1);else blob(out,bytes);}static byte[] bound(DataInputStream in)throws IOException{int n=in.readInt();if(n==-1)return null;if(n<0 || n>NativeSstImportManifest.MAX_KEY_BYTES || n>in.available())throw new IOException("Invalid backup key bound");return in.readNBytes(n);}
}
